-- Separate pages remain incomplete evidence until a reviewer pairs their times.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.no_plan();
INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES
 ('ae100000-0000-4000-8000-000000000001','authenticated','authenticated','separate-pages-owner@local.test',now(),'{}','{"username":"separate_pages_owner"}',now(),now()),
 ('ae100000-0000-4000-8000-000000000002','authenticated','authenticated','separate-pages-person@local.test',now(),'{}','{"username":"separate_pages_person"}',now(),now());
INSERT INTO public.projects(id,creator_id,title,location,description,event_type,verification_method,schedule,status,project_timezone) VALUES
 ('ae200000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001','Separate pages fixture','Local','Synthetic scan evidence','oneTime','manual','{"oneTime":{"date":"2021-08-11","startTime":"09:00","endTime":"12:00","volunteers":5}}','upcoming','UTC');
INSERT INTO public.project_signups(id,project_id,user_id,schedule_id,status) VALUES
 ('ae300000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000002','oneTime','approved');
INSERT INTO public.project_paper_scan_batches(id,project_id,schedule_id,created_by,status,image_count) VALUES
 ('ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','oneTime','ae100000-0000-4000-8000-000000000001','review',2);
INSERT INTO public.project_paper_scan_images(id,batch_id,project_id,object_path,sequence,byte_size,content_type) VALUES
 ('ae500000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','synthetic/separate-pages/sign-in.png',0,100,'image/png'),
 ('ae500000-0000-4000-8000-000000000002','ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','synthetic/separate-pages/sign-out.png',1,100,'image/png');
INSERT INTO public.project_paper_scan_rows(id,batch_id,project_id,image_id,sheet_row_number,raw_extraction,name,decision,match_signup_id,attendance_intervals) VALUES
 ('ae600000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','ae500000-0000-4000-8000-000000000001',1,'{"page":"sign-in","name":"Page volunteer","timeIn":"9:00 AM","timeOut":null}','Page volunteer','include','ae300000-0000-4000-8000-000000000001','[{"checkIn":"2021-08-11T09:00:00Z","checkOut":null}]'),
 ('ae600000-0000-4000-8000-000000000002','ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','ae500000-0000-4000-8000-000000000002',2,'{"page":"sign-out","name":"Page volunteer","timeIn":null,"timeOut":"10:45 AM"}','Page volunteer','include','ae300000-0000-4000-8000-000000000001','[{"checkIn":null,"checkOut":"2021-08-11T10:45:00Z"}]');
CREATE TEMP TABLE page_sources AS SELECT id,image_id,raw_extraction FROM public.project_paper_scan_rows WHERE batch_id='ae400000-0000-4000-8000-000000000001';
CREATE TEMP TABLE page_images AS SELECT id,to_jsonb(images) AS snapshot FROM public.project_paper_scan_images images WHERE batch_id='ae400000-0000-4000-8000-000000000001';

SELECT extensions.throws_ok($$SELECT public.combine_paper_attendance_rows('ae200000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001','ae600000-0000-4000-8000-000000000001',ARRAY['ae600000-0000-4000-8000-000000000002']::uuid[],'ae700000-0000-4000-8000-000000000001')$$,'22023','confirm an uncommitted identity before combining','matching roster proposals alone do not authorize combining');
SELECT public.update_paper_scan_review_row('ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001',id,'ae100000-0000-4000-8000-000000000001','{"expectedRevision":0,"identityConfirmed":true}') FROM public.project_paper_scan_rows WHERE batch_id='ae400000-0000-4000-8000-000000000001';
SELECT extensions.is(public.combine_paper_attendance_rows('ae200000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001','ae600000-0000-4000-8000-000000000001',ARRAY['ae600000-0000-4000-8000-000000000002']::uuid[],'ae700000-0000-4000-8000-000000000001'),'ae600000-0000-4000-8000-000000000001'::uuid,'explicit confirmed-identity combine keeps the target');
SELECT extensions.is((SELECT attendance_intervals FROM public.project_paper_scan_rows WHERE id='ae600000-0000-4000-8000-000000000001'),'[{"checkIn":"2021-08-11T09:00:00Z","checkOut":null},{"checkIn":null,"checkOut":"2021-08-11T10:45:00Z"}]'::jsonb,'combine retains both incomplete visits without inventing a pair');
SELECT extensions.ok((SELECT NOT review_acknowledged FROM public.project_paper_scan_rows WHERE id='ae600000-0000-4000-8000-000000000001'),'combined evidence requires a fresh time review');
SELECT extensions.is((SELECT outcome_detail FROM public.project_paper_scan_rows WHERE id='ae600000-0000-4000-8000-000000000002'),'combined_into:ae600000-0000-4000-8000-000000000001','source row keeps an explicit link to the combined target');
SELECT extensions.results_eq($$SELECT id,image_id,raw_extraction FROM public.project_paper_scan_rows WHERE batch_id='ae400000-0000-4000-8000-000000000001' ORDER BY id$$,$$SELECT * FROM page_sources ORDER BY id$$,'combine preserves original extraction and both source-image references');
SELECT extensions.is((SELECT detail FROM public.commit_paper_signup_batch('ae400000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001',ARRAY['ae600000-0000-4000-8000-000000000001']::uuid[],false,'ae700000-0000-4000-8000-000000000002')),'review_required','combining alone cannot save attendance');
SELECT public.update_paper_scan_review_row('ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','ae600000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001','{"expectedRevision":2,"reviewAcknowledged":true}');
SELECT extensions.is((SELECT detail FROM public.commit_paper_signup_batch('ae400000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001',ARRAY['ae600000-0000-4000-8000-000000000001']::uuid[],false,'ae700000-0000-4000-8000-000000000003')),'invalid_time_window','acknowledgement alone cannot resolve missing visit endpoints');
SELECT extensions.throws_ok($$SELECT public.publish_volunteer_hours_transactional('ae100000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','oneTime','[{"signupId":"ae300000-0000-4000-8000-000000000001","checkIn":"2021-08-11T09:00:00Z","checkOut":"2021-08-11T10:45:00Z","intervals":[{"checkIn":"2021-08-11T09:00:00Z","checkOut":null},{"checkIn":null,"checkOut":"2021-08-11T10:45:00Z"}],"attendanceRevision":0}]','hours-publication:v1:'||repeat('ae',32))$$,'22023','attendance requires complete timestamps with a timezone','publication cannot use an envelope to fill incomplete visits');
SELECT extensions.is((SELECT count(*)::integer FROM public.certificates WHERE project_id='ae200000-0000-4000-8000-000000000001'),0,'unresolved pages have no award');
SELECT extensions.is((SELECT attendance_revision FROM public.project_signups WHERE id='ae300000-0000-4000-8000-000000000001'),0,'failed review and publication preserve the original attendance revision');

SELECT public.update_paper_scan_review_row('ae400000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','ae600000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001','{"expectedRevision":3,"attendanceIntervals":[{"checkIn":"2021-08-11T09:00:00Z","checkOut":"2021-08-11T10:45:00Z"}],"reviewAcknowledged":true,"identityConfirmed":true}');
SELECT extensions.is((SELECT outcome FROM public.commit_paper_signup_batch('ae400000-0000-4000-8000-000000000001','ae100000-0000-4000-8000-000000000001',ARRAY['ae600000-0000-4000-8000-000000000001']::uuid[],false,'ae700000-0000-4000-8000-000000000004')),'signup_updated','reviewed complete visit saves to the known signup');
CREATE TEMP TABLE pages_published AS SELECT public.publish_volunteer_hours_transactional('ae100000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','oneTime','[{"signupId":"ae300000-0000-4000-8000-000000000001","checkIn":"2021-08-11T09:00:00Z","checkOut":"2021-08-11T10:45:00Z","attendanceRevision":1}]','hours-publication:v1:'||repeat('ae',32)) AS result;
SELECT extensions.is((SELECT result->>'outcome' FROM pages_published),'accepted','reviewed paired visit publishes');
SELECT extensions.is(public.publish_volunteer_hours_transactional('ae100000-0000-4000-8000-000000000001','ae200000-0000-4000-8000-000000000001','oneTime','[{"signupId":"ae300000-0000-4000-8000-000000000001","checkIn":"2021-08-11T09:00:00Z","checkOut":"2021-08-11T10:45:00Z","attendanceRevision":1}]','hours-publication:v1:'||repeat('ae',32))->>'outcome','replayed','publication retry uses the existing award');
SELECT extensions.is((SELECT count(*)::integer FROM public.certificates WHERE project_id='ae200000-0000-4000-8000-000000000001'),1,'separate pages and retries produce exactly one certificate');
SELECT extensions.is((SELECT credited_minutes FROM public.certificates WHERE signup_id='ae300000-0000-4000-8000-000000000001'),105,'paired visit awards the reviewed actual minutes');
SELECT extensions.is((SELECT count(*)::integer FROM public.hours_publication_email_outbox outbox JOIN public.certificates cert ON cert.id=outbox.certificate_id WHERE cert.project_id='ae200000-0000-4000-8000-000000000001'),1,'separate pages and retries queue exactly one certificate delivery');
SELECT extensions.results_eq($$SELECT id,image_id,raw_extraction FROM public.project_paper_scan_rows WHERE batch_id='ae400000-0000-4000-8000-000000000001' ORDER BY id$$,$$SELECT * FROM page_sources ORDER BY id$$,'resolved publication still preserves original extraction and image references');
SELECT extensions.results_eq($$SELECT id,to_jsonb(images) FROM public.project_paper_scan_images images WHERE batch_id='ae400000-0000-4000-8000-000000000001' ORDER BY id$$,$$SELECT * FROM page_images ORDER BY id$$,'source photo metadata remains unchanged after resolution');
SELECT * FROM extensions.finish();
ROLLBACK;
